def open_mode_selection() -> None:
    """메인 메뉴에서 모드 선택을 엽니다. Normal/Zombie 선택 버튼이 조작 가능해지면 완료합니다."""
    click(selector("Canvas/Main menu/Play button"))

def ready_open_mode_selection() -> bool:
    return actionable(selector("Canvas/Main menu/Play button"))

def effect_open_mode_selection() -> bool:
    return actionable(selector("Canvas/mode menu/back_3"))

def start_normal_mode() -> None:
    """모드 선택 화면에서 Normal 전투를 시작합니다. Map_v2에 도착하면 완료하며 로더 동안 기다립니다."""
    click(selector("Canvas/mode menu/back_3"))

def ready_start_normal_mode() -> bool:
    return actionable(selector("Canvas/mode menu/back_3"))

def effect_start_normal_mode() -> bool:
    return scene() == "Map_v2"

def start_zombie_mode() -> None:
    """모드 선택 화면에서 Zombie 전투를 시작합니다. zombie_level에 도착하면 완료하며 로더 동안 기다립니다."""
    click(selector("Canvas/mode menu/back_2"))

def ready_start_zombie_mode() -> bool:
    return actionable(selector("Canvas/mode menu/back_2"))

def effect_start_zombie_mode() -> bool:
    return scene() == "zombie_level"

def replay_normal_mode() -> None:
    """Normal Game Over에서 Replay를 누릅니다. 새 Map_v2에 도착하면 완료합니다."""
    click(selector("Canvas/Main menu/REPLAY"))

def ready_replay_normal_mode() -> bool:
    return scene() == "game over"

def effect_replay_normal_mode() -> bool:
    return scene() == "Map_v2"

def pause_battle(pause: object) -> None:
    """전투 중 ESC로 일시정지합니다. gamepaused가 켜지면 완료하며 시간 정지는 TC에서 별도 비교합니다."""
    press_key("Escape", 0.1)

def ready_pause_battle(pause: object) -> bool:
    return member(pause, "pause_menu_script.gamepaused") == False

def effect_pause_battle(pause: object) -> bool:
    return member(pause, "pause_menu_script.gamepaused") == True

def resume_battle(pause: object) -> None:
    """일시정지 상태에서 ESC로 전투를 재개합니다. gamepaused가 꺼지면 완료하며 시간 재개는 TC에서 비교합니다."""
    press_key("Escape", 0.1)

def ready_resume_battle(pause: object) -> bool:
    return member(pause, "pause_menu_script.gamepaused") == True

def effect_resume_battle(pause: object) -> bool:
    return member(pause, "pause_menu_script.gamepaused") == False

def move_forward(character: object) -> None:
    """전투 중 앞으로 1초 이동 입력을 보냅니다. 이동 결과는 고정 지형이나 플레이어 위치를 비교합니다."""
    press_key("W", 1.0)

def ready_move_forward(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False

def fire_once(character: object) -> None:
    """전투 중 마우스 왼쪽 버튼을 한 번 눌렀다 뗍니다. 단발 무기를 준비하고 잔탄 감소는 TC에서 비교합니다."""
    hold_mouse_button(0)
    release_mouse_button(0)

def ready_fire_once(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False

def switch_weapon(character: object) -> None:
    """전투 중 Q로 다음 무기 전환을 요청합니다. 전환 완료 후 모델과 HUD를 TC에서 비교합니다."""
    press_key("Q", 0.1)

def ready_switch_weapon(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False

def press_reload(character: object) -> None:
    """전투 중 R을 한 번 누릅니다. 탄약 상자 거리와 잔탄에 따른 재장전 또는 거부 결과를 TC에서 판정합니다."""
    press_key("R", 0.1)

def ready_press_reload(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False

def use_medikit(character: object) -> None:
    """전투 중 CapsLock을 한 번 누릅니다. 회복 및 거리 제한 결과는 TC에서 체력과 대상 키트를 비교합니다."""
    press_key("CapsLock", 0.1)

def ready_use_medikit(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False

def throw_grenade(character: object) -> None:
    """전투 중 G를 한 번 누릅니다. 투척체가 제거된 뒤 수류탄 보유 수 감소는 TC에서 판정합니다."""
    press_key("G", 0.1)

def ready_throw_grenade(character: object) -> bool:
    if scene() == "Map_v2":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    if scene() == "zombie_level":
        return member(character, "InfimaGames.LowPolyShooterPack.Character.cursorLocked") == True
    return False
